<?php
require '../config/config.php'; role(['administrator','pustakawan']);
if($_SERVER['REQUEST_METHOD']==='POST'){
  try{
    $code=trim($_POST['code']??'');$isbn=trim($_POST['isbn']??'');$title=trim($_POST['title']??'');$author=trim($_POST['author']??'');$publisher=trim($_POST['publisher']??'');$year=(int)($_POST['publication_year']??0);$cat=(int)($_POST['category_id']??0)?:null;$qty=max(1,(int)($_POST['quantity']??1));$loc=(int)($_POST['location_id']??0)?:null;$cond=$_POST['condition_status']??'baik';$status=$_POST['status']??'tersedia';
    if($code===''||$title==='')throw new Exception('Kode/inventaris dan judul wajib diisi.');
    if(!in_array($cond,['baik','rusak ringan','rusak berat'],true))$cond='baik';if(!in_array($status,['tersedia','dipinjam','rusak','hilang'],true))$status='tersedia';
    $pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO books(code,isbn,title,author,publisher,publication_year,category_id) VALUES(?,?,?,?,?,?,?)');$q->execute([$code,$isbn?:null,$title,$author,$publisher,$year?:null,$cat]);$bookId=$pdo->lastInsertId();
    $q=$pdo->prepare('INSERT INTO copies(book_id,code,location_id,condition_status,status) VALUES(?,?,?,?,?)');for($i=1;$i<=$qty;$i++)$q->execute([$bookId,$code.'-'.str_pad($i,2,'0',STR_PAD_LEFT),$loc,$cond,$status]);$pdo->commit();setmsg("Buku berhasil ditambahkan dengan $qty eksemplar.");header('Location:books.php');exit;
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();setmsg($e->getMessage(),'danger');}
}
$cats=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$locs=$pdo->query('SELECT id,name FROM locations ORDER BY name')->fetchAll();
$r=$pdo->query("SELECT b.*,cat.name category_name,COUNT(c.id) total_copies,COALESCE(SUM(c.status='tersedia'),0) available,COALESCE(SUM(c.status='dipinjam'),0) borrowed,COALESCE(SUM(c.status='rusak'),0) damaged,COALESCE(SUM(c.status='hilang'),0) lost FROM books b LEFT JOIN categories cat ON cat.id=b.category_id LEFT JOIN copies c ON c.book_id=b.id GROUP BY b.id ORDER BY b.title")->fetchAll();
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Data Buku - Perpustakaan SMPIT</title><link rel=stylesheet href=../public/style.css><style>.bookgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.hint{font-size:12px;color:#64748b}@media(max-width:900px){.bookgrid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.bookgrid{grid-template-columns:1fr}}</style></head><body><div class=layout><?php include '../public/nav.php'?><main class=main><h1>📚 Data Buku</h1><?php msg()?><div class=form><h3>Tambah Buku dan Eksemplar</h3><p class=hint>Setiap eksemplar otomatis mendapat barcode unik, misalnya BK-0001-01, BK-0001-02, dan seterusnya.</p><form method=post><div class=bookgrid>
<div><label>Kode / Inventaris</label><input name=code placeholder="BK-0001" required></div><div><label>ISBN</label><input name=isbn placeholder="978-..."></div><div><label>Judul Buku</label><input name=title required></div><div><label>Penulis</label><input name=author></div><div><label>Penerbit</label><input name=publisher></div><div><label>Tahun Terbit</label><input type=number name=publication_year min=1000 max=2100></div>
<div><label>Kategori</label><select name=category_id><option value="">-- Pilih kategori --</option><?php foreach($cats as $c):?><option value=<?=$c['id']?>><?=e($c['name'])?></option><?php endforeach?></select></div><div><label>Jumlah Eksemplar</label><input type=number name=quantity min=1 value=1 required></div><div><label>Lokasi / Rak</label><select name=location_id><option value="">-- Pilih lokasi --</option><?php foreach($locs as $l):?><option value=<?=$l['id']?>><?=e($l['name'])?></option><?php endforeach?></select></div><div><label>Kondisi</label><select name=condition_status><option>baik</option><option>rusak ringan</option><option>rusak berat</option></select></div><div><label>Status</label><select name=status><option>tersedia</option><option>dipinjam</option><option>rusak</option><option>hilang</option></select></div></div><button>+ Simpan Buku</button></form></div><div class=table-wrap><table class=table><tr><th>Kode</th><th>ISBN</th><th>Judul</th><th>Penulis</th><th>Penerbit</th><th>Tahun</th><th>Kategori</th><th>Eksemplar</th><th>Ketersediaan</th></tr><?php foreach($r as $x):?><tr><td><b><?=e($x['code'])?></b></td><td><?=e($x['isbn']?:'-')?></td><td><?=e($x['title'])?></td><td><?=e($x['author']?:'-')?></td><td><?=e($x['publisher']?:'-')?></td><td><?=e($x['publication_year']?:'-')?></td><td><?=e($x['category_name']?:'-')?></td><td><?=$x['total_copies']?></td><td>🟢 <?=$x['available']?> tersedia<br>🔴 <?=$x['borrowed']?> dipinjam<br>⚠️ <?=$x['damaged']?> rusak · ❌ <?=$x['lost']?> hilang</td></tr><?php endforeach?><?php if(!$r):?><tr><td colspan=9>Belum ada data buku.</td></tr><?php endif?></table></div></main></div></body></html>
